fields.ValueConv:
my $unixTimeZero = 134774 * 24 * 3600;
my @vals = split ' ', $val;
foreach (@vals) {
    if (/[^0-9a-f]/i) {
        $_ = '0000:00:00 00:00:00';
    } elsif (length $_ > 8) {
        my $lo = hex substr($_, -8);
        my $hi = hex substr($_, 0, -8);
        $_ = 1e-7 * ($hi * 4294967296 + $lo);
    } else {
        $_ = 1e-7 * hex($_);
    }
    # shift from Jan 1, 1601 to Jan 1, 1970
    $_ = Image::ExifTool::ConvertUnixTime($_ - $unixTimeZero);
}
return \@vals;
